//! Throughput benchmarks across the library.
//!
//! Every input is **generated by the simulator** rather than loaded from a fixture. That is what
//! makes this possible at all: before the simulator there was no committed recording large enough
//! to benchmark against, and a fixture big enough to be interesting is too big to keep in a
//! repository. Generating from a seed instead gives reproducible input at any size, so a change in
//! the numbers is a change in the code rather than in the data.
//!
//! Run with `cargo bench -p eventcv-core`.

use std::hint::black_box;

use criterion::{criterion_group, criterion_main, BenchmarkId, Criterion, Throughput};

use eventcv_core::cmax::{CmaxConfig, Objective, WarpModel};
use eventcv_core::representation::Representation;
use eventcv_core::simulate::{Simulator, SimulatorConfig, Upsample};
use eventcv_core::track::{Tracker, TrackerConfig};
use eventcv_core::EventStream;

/// A moving-bar recording, simulated. Deterministic for a given size and frame count.
fn scene(width: usize, height: usize, frames: usize) -> EventStream {
    let mut simulator = Simulator::new(
        width,
        height,
        SimulatorConfig {
            // Noise off: benchmarks should measure the code path, not a random event count that
            // drifts with the RNG.
            sigma_thres: 0.0,
            leak_rate_hz: 0.0,
            shot_noise_rate_hz: 0.0,
            cutoff_hz: 0.0,
            upsample: Upsample::Off,
            ..SimulatorConfig::default()
        },
    );
    let mut slices = Vec::with_capacity(frames);
    for frame in 0..frames {
        let bar = frame * width / frames.max(1);
        let mut luma = vec![0.05_f32; width * height];
        for y in 0..height {
            for offset in 0..6 {
                if bar + offset < width {
                    luma[y * width + bar + offset] = 0.9;
                }
            }
        }
        slices.push(simulator.push_frame(&luma, frame as i64 * 1_000));
    }
    match slices.split_first() {
        Some((first, rest)) => first.concat(&rest.iter().collect::<Vec<_>>()),
        None => unreachable!("frames were pushed"),
    }
}

fn representations(c: &mut Criterion) {
    let stream = scene(346, 260, 40);
    let mut group = c.benchmark_group("representations");
    // Throughput in events makes the numbers comparable across sensor sizes rather than only
    // against themselves.
    group.throughput(Throughput::Elements(stream.len() as u64));

    group.bench_function("count", |b| {
        b.iter(|| black_box(eventcv_core::representation::EventCount::new(false).generate(&stream)))
    });
    group.bench_function("voxel_5", |b| {
        b.iter(|| {
            black_box(eventcv_core::representation::VoxelGrid::new(5, 30.0).generate(&stream))
        })
    });
    group.bench_function("time_surface", |b| {
        b.iter(|| black_box(eventcv_core::representation::TimeSurface::new(30.0).generate(&stream)))
    });
    group.finish();
}

fn filters_and_transforms(c: &mut Criterion) {
    let stream = scene(346, 260, 40);
    let mut group = c.benchmark_group("stream_ops");
    group.throughput(Throughput::Elements(stream.len() as u64));

    group.bench_function("flip_x", |b| b.iter(|| black_box(stream.flip_x())));
    group.bench_function("hot_pixel_filter", |b| {
        b.iter(|| black_box(stream.hot_pixel_filter(3.0)))
    });
    group.bench_function("refractory_filter", |b| {
        b.iter(|| black_box(stream.refractory_filter(1_000)))
    });
    group.bench_function("event_drop", |b| {
        b.iter(|| black_box(stream.event_drop(0.5, 0)))
    });
    group.finish();
}

fn simulation(c: &mut Criterion) {
    let mut group = c.benchmark_group("simulate");
    // Per pixel-frame rather than per event: the simulator's cost is driven by how many pixels it
    // integrates, not by how many events happen to come out.
    for (width, height) in [(128, 96), (346, 260)] {
        let frames = 20;
        group.throughput(Throughput::Elements((width * height * frames) as u64));
        group.bench_with_input(
            BenchmarkId::from_parameter(format!("{width}x{height}")),
            &(width, height, frames),
            |b, &(width, height, frames)| b.iter(|| black_box(scene(width, height, frames))),
        );
    }
    group.finish();
}

fn contrast_maximisation(c: &mut Criterion) {
    // Smaller sensor: CMax runs hundreds of warp-and-score passes, and a full-size sensor would
    // make one sample take seconds.
    let stream = scene(128, 96, 20);
    let mut group = c.benchmark_group("cmax");
    group.throughput(Throughput::Elements(stream.len() as u64));
    group.sample_size(20);

    group.bench_function("iwe", |b| {
        b.iter(|| black_box(stream.iwe(WarpModel::Translation, &[100.0, 0.0])))
    });
    for objective in [Objective::Variance, Objective::SumOfSquares] {
        group.bench_with_input(
            BenchmarkId::new("optimise", format!("{objective:?}")),
            &objective,
            |b, &objective| {
                b.iter(|| {
                    black_box(stream.contrast_maximise(
                        WarpModel::Translation,
                        CmaxConfig {
                            objective,
                            ..CmaxConfig::default()
                        },
                    ))
                })
            },
        );
    }
    group.finish();
}

fn tracking(c: &mut Criterion) {
    let stream = scene(346, 260, 40);
    let frame = eventcv_core::representation::EventCount::new(false)
        .generate(&stream)
        .expect("count representation should build");
    let mut group = c.benchmark_group("track");
    group.bench_function("connected_components", |b| {
        b.iter(|| black_box(frame.connected_components(8)))
    });
    group.bench_function("tracker_update", |b| {
        b.iter(|| {
            let mut tracker = Tracker::new(TrackerConfig::default());
            // `update` returns a borrow of the tracker, which cannot outlive this closure — count
            // the tracks instead so the work is still done and measured.
            black_box(tracker.update(&frame).map(|tracks| tracks.len()))
        })
    });
    group.finish();
}

criterion_group!(
    benches,
    representations,
    filters_and_transforms,
    simulation,
    contrast_maximisation,
    tracking
);
criterion_main!(benches);
